// Exam 4 · Test bank — written for this site. a = index of the right option, or an array for select-all-that-apply.
// link = where to study it (#c-<condition> or #t-<topic>). wk = syllabus week.
window.MH_Q = [
// ---------- Week 11 ----------
{ id: 'q-intro-1', wk: 11, link: 't-intro', stem: 'Which statement best describes mental health?', opts: ['The absence of a psychiatric diagnosis', 'A state of well-being in which a person copes with normal stress, works productively and contributes to the community', 'Feeling happy most of the time', 'Behavior that matches the majority of people in one’s community'], a: 1, why: 'Mental health is a state of **well-being and functioning**, not just the absence of illness or constant happiness. Cultural norms matter, but “being like the majority” isn’t the definition.' },
{ id: 'q-intro-2', wk: 11, link: 't-intro', stem: 'A nurse says, “Recovery means the symptoms are gone for good.” Which response by the charge nurse is most accurate?', opts: ['“Yes, recovery is the same as cure.”', '“Recovery is a process of living a self-directed, meaningful life, even if some symptoms remain.”', '“Recovery only applies to substance use.”', '“Recovery happens only after hospitalization.”'], a: 1, why: 'Recovery is a **process** focused on hope, self-direction and reaching potential; symptoms may persist.' },
{ id: 'q-dx-1', wk: 11, link: 't-dx', stem: 'The nurse documents: “Patient states she feels ‘great’ while crying.” This finding is best described as:', opts: ['Labile mood', 'Affect incongruent with stated mood', 'Flight of ideas', 'Poor insight'], a: 1, why: '**Mood** is what she reports (“great”); **affect** is what you observe (crying). They don’t match: **incongruent**.' },
{ id: 'q-dx-2', wk: 11, link: 't-dx', stem: 'A patient newly diagnosed with depression has fatigue, weight gain, cold intolerance and dry skin. Which lab should the nurse expect first?', opts: ['Serum lithium', 'TSH', 'Troponin', 'Serum ammonia'], a: 1, why: 'These are signs of **hypothyroidism**, which can mimic depression. A **TSH** rules out a medical cause.' },
{ id: 'q-dx-3', wk: 11, link: 't-dx', stem: 'Which parts belong in the mental status exam? Select all that apply.', opts: ['Appearance and behavior', 'Mood and affect', 'Thought process and thought content', 'Insurance status', 'Insight and judgment'], a: [0, 1, 2, 4], why: 'The MSE covers appearance, behavior, speech, mood and affect, thought, perception, cognition, insight and judgment. Insurance is not part of it.' },
{ id: 'q-life-1', wk: 11, link: 't-life', stem: 'A 74-year-old patient says, “I made so many mistakes. My life was a waste.” According to Erikson, this reflects:', opts: ['Generativity vs self-absorption', 'Integrity vs despair, unresolved', 'Intimacy vs isolation', 'Identity vs role confusion'], a: 1, why: 'Later life: **integrity vs despair**. Regret and hopelessness reflect **despair**. Explore life review and screen for depression.' },
{ id: 'q-life-2', wk: 11, link: 't-life', stem: 'Which developmental task does the nurse expect of a 45-year-old?', opts: ['Establishing a sense of identity', 'Developing close, committed relationships', 'Guiding the next generation and contributing to society', 'Accepting one’s life and approaching death with dignity'], a: 2, why: 'Middle adulthood (35–65): **generativity vs self-absorption (stagnation)**.' },
{"id":"q-set-1","wk":11,"link":"t-settings","stem":"Which describes assertive community treatment (ACT)?","opts":["A locked inpatient unit for long-term stays and stabilization","A mobile community team available 24 hours for serious mental illness","Weekly outpatient therapy with one assigned therapist","A peer-run self-help group that meets in the community"],"a":1,"why":"ACT teams bring intensive, 24/7 care to people with serious mental illness wherever they live.","optionWhy":["A locked inpatient unit is a facility-based service, not a mobile community team.","Correct: ACT brings a coordinated, intensive team to people living in the community, with round-the-clock availability.","A weekly appointment is less intensive and does not provide the team-based, continuous community support described.","A peer-run self-help group is a different service and is not the coordinated ACT team."]},
{ id: 'q-set-2', wk: 11, link: 't-settings', stem: 'Which event led to deinstitutionalization in the United States?', opts: ['The HIPAA Privacy Rule', 'The Community Mental Health Centers Act of 1963', 'The Tarasoff ruling', 'The Mental Health Parity Act'], a: 1, why: 'The 1963 Act moved care from state hospitals to community mental health centers (helped by the first antipsychotics in the 1950s).', optionWhy: ['HIPAA protects health information; it did not drive the shift from state hospitals to community care.', 'Correct: this act supported community mental health centers as care shifted away from large state institutions.', 'Tarasoff concerns a duty to protect an identifiable person from a serious threat, not the organization of community services.', 'Parity law concerns insurance coverage limits, not the historical move to community-based care.'] },
{"id":"q-legal-1","wk":11,"link":"t-legal","stem":"A patient admitted involuntarily refuses his oral antipsychotic. He is calm and not threatening. What is the nurse’s best action?","opts":["Give the medication IM, since he is involuntarily admitted","Explore his reasons, document and notify the provider","Restrict him to his room until he takes it","Crush it and mix it into his food so he gets the dose"],"a":1,"why":"Involuntarily committed patients **keep the right to refuse** treatment outside an emergency or a court order. Forcing it would be **battery**.","optionWhy":["An involuntary admission alone does not authorize forced medication when there is no emergency or applicable order.","Correct: respect the stated choice, learn the patient’s concern, document it, and notify the prescriber for follow-up.","Room restriction is coercive and does not resolve the medication refusal or create legal authority to force treatment.","Hiding medication removes informed choice and is not an acceptable way to bypass a refusal."]},
{ id: 'q-legal-2', wk: 11, link: 't-legal', stem: 'An adult patient is placed in restraints for violent behavior. Which actions are correct? Select all that apply.', opts: ['Obtain a provider order, which lasts up to 4 hours for an adult', 'Write the order as PRN for future episodes', 'Observe the patient continuously', 'Offer fluids and toileting and check circulation at regular intervals', 'Release as soon as the patient can safely be released'], a: [0, 2, 3, 4], why: 'Orders are **never PRN or standing**. Adult orders last **4 hours** (renewable up to 24). Continuous observation, regular checks and the earliest safe release are required.', optionWhy: ['Correct: an order is required, with the time limit described in the course material for an adult.', 'Incorrect: a restraint order cannot authorize a future episode as a PRN or standing order.', 'Correct: close observation is needed to monitor safety while restraint is in use.', 'Correct: regular physical-needs and circulation checks reduce preventable harm.', 'Correct: end restraint as soon as the immediate safety need has passed.'] },
{ id: 'q-legal-3', wk: 11, link: 't-legal', stem: 'A voluntarily admitted patient demands to be discharged. What should the nurse do first?', opts: ['Tell the patient he must complete treatment first', 'Notify the provider so the patient can be evaluated', 'Place the patient in seclusion', 'Call security to escort him off the unit'], a: 1, why: 'Voluntary patients may **request release**. The provider evaluates; a hold is possible only if he is dangerous. Holding him without grounds = **false imprisonment**.', optionWhy: ['Voluntary status does not require the patient to finish a treatment plan before requesting discharge.', 'Correct: promptly notify the provider so the request and any legal safety criteria can be evaluated.', 'Seclusion is not a response to a discharge request and requires a separate immediate safety basis.', 'Security cannot substitute for the required clinical and legal evaluation of the request.'] },
{"id":"q-legal-4","wk":11,"link":"t-legal","stem":"A patient tells the nurse he plans to kill his neighbor when discharged. The priority action is to:","opts":["Keep it confidential to protect the therapeutic relationship","Report it to the treatment team and provider immediately","Document it and reassess his intent tomorrow","Ask the patient to promise not to do it"],"a":1,"why":"A serious threat against an **identifiable** person triggers the **duty to warn and protect** (Tarasoff), an exception to confidentiality.","optionWhy":["Confidentiality has safety-related exceptions; the stated threat cannot simply be kept private.","Correct: report the specific threat immediately so the team can assess and take protective action.","Documentation matters, but delaying action until tomorrow leaves an urgent threat unaddressed.","A promise does not assess or reduce the concrete risk enough to replace escalation."]},
{"id":"q-legal-5","wk":11,"link":"t-legal","stem":"Which situation is false imprisonment?","opts":["Restraining a patient who is attacking staff, with an order","Keeping a voluntary patient locked in after he asks to leave, with no hold","Placing a suicidal patient on 1:1 observation that limits where he goes","Asking a patient to stay in the dayroom while staff complete room checks"],"a":1,"why":"Confining someone without **legal grounds** is false imprisonment.","optionWhy":["A justified restraint with the required order is not the described example of confinement without legal authority.","Correct: preventing a voluntary patient from leaving without a valid hold unlawfully restricts liberty.","Observation increases supervision but does not itself confine the patient against their will.","A temporary request to remain in a shared area is not the same as unlawfully detaining the patient."]},
{ id: 'q-legal-6', wk: 11, link: 't-legal', stem: 'The nurse explains the side effects of a new antidepressant honestly, including sexual dysfunction. Which ethical principle is the nurse demonstrating?', opts: ['Justice', 'Fidelity', 'Veracity', 'Beneficence'], a: 2, why: '**Veracity** = truthfulness.', optionWhy: ['Justice concerns fairness in care, not the specific act of telling the truth about side effects.', 'Fidelity is keeping commitments and maintaining trust; this example centers on accurate disclosure.', 'Correct: veracity means giving truthful information, including relevant adverse effects.', 'Beneficence means acting for the patient’s good; the behavior described is specifically truth-telling.'] },
{ id: 'q-theory-1', wk: 11, link: 't-theories', stem: 'A patient with a fear of elevators first looks at pictures of elevators, then stands near one, then rides one floor, using relaxation at each step. This is:', opts: ['Flooding', 'Aversion therapy', 'Systematic desensitization', 'Psychoanalysis'], a: 2, why: '**Graded** exposure paired with relaxation = systematic desensitization. Flooding is intense, all-at-once exposure.' },
{ id: 'q-theory-2', wk: 11, link: 't-theories', stem: 'Using Maslow’s hierarchy, which need should the nurse address first in a newly admitted patient with acute mania?', opts: ['Self-esteem', 'Belonging in group therapy', 'Nutrition, fluids and rest', 'Insight into the illness'], a: 2, why: '**Physiological** needs come first; a manic patient who hasn’t eaten or slept is at physical risk.' },
{ id: 'q-rel-1', wk: 11, link: 't-relationship', stem: 'In which phase of the nurse–patient relationship are the terms of the contract, including when the relationship will end, established?', opts: ['Preorientation', 'Orientation', 'Working', 'Termination'], a: 1, why: 'The **orientation** phase sets the contract: purpose, time, place, confidentiality and the **end date**.', optionWhy: ['Preorientation is the nurse’s preparation before the first meeting, not the shared agreement with the patient.', 'Correct: the orientation phase establishes the relationship, goals, boundaries and planned ending.', 'The working phase uses the established relationship to address concerns and practise coping.', 'Termination is when the relationship is brought to its planned close, not when its terms are first set.'] },
{"id":"q-rel-2","wk":11,"link":"t-relationship","stem":"A nurse notices she is spending much more time with one patient than with others and has shared details of her own divorce. What is happening?","opts":["Transference","Boundary crossing","Termination","Therapeutic self-disclosure"],"a":1,"why":"Extra time and excessive self-disclosure are signs of **boundary crossing**: the relationship is drifting toward the nurse’s needs. The nurse is responsible for refocusing and seeking supervision.","optionWhy":["Transference is the patient directing feelings from a past relationship toward the nurse; the stem describes the nurse’s conduct.","Correct: unequal extra time and personal disclosure suggest the professional relationship is drifting beyond its patient-focused limits.","Termination is the planned ending phase; no ending is described.","Self-disclosure is therapeutic only when brief and for the patient’s benefit; sharing divorce details and giving extra time serve the nurse."]},
{ id: 'q-rel-3', wk: 11, link: 't-relationship', stem: 'A patient becomes angry at a nurse, saying, “You’re bossy just like my mother.” The nurse recognizes this as:', opts: ['Countertransference', 'Transference', 'Projection by the nurse', 'Splitting'], a: 1, why: 'The **patient** transfers feelings about someone from the past onto the nurse = **transference**.', optionWhy: ['Countertransference is the nurse’s own past feelings influencing care; this reaction is expressed by the patient.', 'Correct: the patient is responding to the nurse through feelings associated with a past relationship.', 'Projection is attributing one’s own unacceptable feelings to someone else; the stem points to a past relationship being replayed.', 'Splitting describes viewing people or situations in extreme all-good or all-bad terms, not this specific past-to-present relationship pattern.'] },
{"id":"q-comm-1","wk":11,"link":"t-comm","stem":"A patient says, “I don’t know why I bother. Nobody cares if I live or die.” Which response is most therapeutic?","opts":["“Of course people care about you. Your family visits every day.”","“You feel no one cares. Are you thinking about ending your life?”","“Why do you feel that way?”","“Let’s focus on your plans for discharge and things to look forward to.”"],"a":1,"why":"Reflects the feeling and **asks directly about suicide**. The others reassure, ask “why,” or change the subject.","optionWhy":["Reassurance may sound comforting but does not establish whether the patient is in immediate danger.","Correct: reflect the expressed feeling, then ask a clear safety question to assess suicidal thoughts.","A “why” question can feel judgmental and does not directly clarify current suicide risk.","Changing to discharge planning skips the immediate safety cue in the patient’s statement."]},
{ id: 'q-comm-2', wk: 11, link: 't-comm', stem: 'Which nurse statements are nontherapeutic? Select all that apply.', opts: ['“Why did you stop taking your medication?”', '“Tell me more about what happened.”', '“Don’t worry, everything will be fine.”', '“If I were you, I would call your sister.”', '“You seem upset.”'], a: [0, 2, 3], why: 'A “why” question, false reassurance and advice are blocks. Exploring and making observations are therapeutic.', optionWhy: ['Correct: asking “why” can sound accusatory and pressures the patient to defend a choice.', 'This invites the patient to share more without judgment, so it is therapeutic exploration.', 'Correct: promising that everything will be fine is unsupported reassurance and can close discussion.', 'Correct: giving personal advice replaces the patient’s decision-making with the nurse’s preference.', 'An observation stated tentatively invites the patient to respond and clarify their feelings.'] },
{"id":"q-comm-3","wk":11,"link":"t-comm","stem":"A patient says, “The CIA is listening through the TV.” The best response is:","opts":["“That’s impossible. The TV can’t listen to anyone, so try to relax.”","“What is the CIA saying to you?”","“That must be frightening. I don’t hear anything, but I’m here.”","“I’ll unplug the TV so they can’t hear you.”"],"a":2,"why":"Acknowledge the **feeling**, **present reality** without arguing, and offer support. Don’t argue, explore the delusion’s content, or act as if it’s real.","optionWhy":["Directly disputing the belief can make the patient feel dismissed and does not build trust.","This question treats the belief as factual and explores its details rather than grounding the patient.","Correct: recognize the fear, state the nurse’s perception without arguing, and offer calm support.","Acting on the belief implies agreement that the TV is transmitting the patient’s thoughts."]},
{ id: 'q-stress-1', wk: 11, link: 't-stress', stem: 'A student says, “I’m not going to think about my parents’ divorce until after my finals.” This is:', opts: ['Repression', 'Suppression', 'Denial', 'Displacement'], a: 1, why: '**Suppression** is a **conscious** choice to postpone dealing with something. Repression is unconscious.' },
{ id: 'q-stress-2', wk: 11, link: 't-stress', stem: 'A man who is angry with his supervisor goes home and yells at his dog. Which defense mechanism is this?', opts: ['Projection', 'Displacement', 'Sublimation', 'Rationalization'], a: 1, why: '**Displacement**: feelings move from a threatening target to a safer one.' },
{ id: 'q-stress-3', wk: 11, link: 't-stress', stem: 'Which finding is expected during the alarm stage of the stress response?', opts: ['Bradycardia and pupil constriction', 'Tachycardia, increased blood glucose and dilated pupils', 'Decreased cortisol', 'Increased digestion'], a: 1, why: 'Alarm = **sympathetic** fight-or-flight: epinephrine raises heart rate and glucose and dilates pupils; digestion slows.' },
{ id: 'q-stress-4', wk: 11, link: 't-stress', stem: 'A patient with moderate anxiety is missing parts of the teaching. What should the nurse do?', opts: ['Stop teaching until tomorrow', 'Give brief, focused information and help the patient refocus', 'Give a PRN benzodiazepine and restrain', 'Teach faster to cover everything'], a: 1, why: 'At **moderate** anxiety the perceptual field narrows but the patient can still learn and problem-solve **with help**.' },
{ id: 'q-trauma-1', wk: 11, link: 't-trauma', stem: 'Which approaches reflect trauma-informed care? Select all that apply.', opts: ['Explaining each procedure before doing it', 'Offering choices whenever possible', 'Asking “What happened to you?” rather than “What’s wrong with you?”', 'Using restraint early to prevent escalation', 'Asking before touching the patient'], a: [0, 1, 2, 4], why: 'Trauma-informed care emphasizes safety, transparency, choice and collaboration. Early restraint can **retraumatize**.' },
// ---------- Week 12 ----------
{ id: 'q-bp-1', wk: 12, link: 'c-bipolar', stem: 'A patient on lithium has a level of 1.9 mEq/L, vomiting, a coarse hand tremor and confusion. The nurse should first:', opts: ['Give the next dose with food', 'Hold the lithium and notify the provider', 'Encourage a low-sodium diet', 'Reassure the patient that these effects are expected'], a: 1, why: '1.5–2.0 with GI symptoms, coarse tremor and confusion = **early toxicity**: hold the dose, get a level, notify the provider.' },
{ id: 'q-bp-2', wk: 12, link: 'c-bipolar', stem: 'Which teaching points are correct for a patient starting lithium? Select all that apply.', opts: ['Keep sodium intake consistent', 'Drink 1.5–3 L of fluid a day', 'Ibuprofen is a safe choice for headaches', 'Call the provider if you have vomiting, diarrhea or heavy sweating', 'Stop lithium once your mood is stable'], a: [0, 1, 3], why: 'Lithium follows sodium and water: keep both steady; fluid loss raises the level. **NSAIDs raise** lithium levels. It is continued after the episode to prevent relapse.' },
{"id":"q-bp-3","wk":12,"link":"c-bipolar","stem":"A patient with acute mania has not eaten in 2 days and is pacing constantly. Which intervention is best?","opts":["Ask her to sit down for a full, balanced meal in the dining room","Offer high-calorie finger foods she can eat while moving","Wait until she is hungry","Schedule her for the unit’s afternoon nutrition group"],"a":1,"why":"Distractibility and hyperactivity keep her from sitting through a meal: **finger foods and drinks “on the run.”**"},
{ id: 'q-bp-4', wk: 12, link: 'c-bipolar', stem: 'Which activity is most appropriate for a patient in acute mania?', opts: ['A competitive volleyball game', 'Walking with a staff member in a quiet hallway', 'Leading a community meeting', 'Watching an action movie in the dayroom'], a: 1, why: '**Solitary, noncompetitive physical activity** in a low-stimulation area burns energy without escalating.' },
{ id: 'q-bp-5', wk: 12, link: 'c-bipolar', stem: 'A patient taking valproate needs which monitoring? Select all that apply.', opts: ['Liver function tests', 'Platelet count', 'Pregnancy status', 'Serum lithium level', 'Signs of pancreatitis'], a: [0, 1, 2, 4], why: 'Valproate: **hepatotoxicity, thrombocytopenia, pancreatitis** and **teratogenicity** (neural tube defects). A lithium level isn’t relevant.' },
{"id":"q-bp-6","wk":12,"link":"c-bipolar","stem":"What distinguishes hypomania from mania?","opts":["Hypomania lasts longer than a manic episode","Hypomania causes no marked impairment or psychosis","Hypomania occurs together with a depressive episode","Only mania involves an elevated or irritable mood"],"a":1,"why":"Hypomania (4+ days) is a noticeable change **without marked impairment or psychosis**; mania (1+ week) causes marked impairment and can include psychosis."},
{ id: 'q-mdd-1', wk: 12, link: 'c-mdd', stem: 'A patient with depression who started an antidepressant 2 weeks ago has more energy and is more talkative. The nurse should:', opts: ['Reduce suicide precautions since he is improving', 'Continue close monitoring for suicide risk', 'Discontinue the medication', 'Discharge him to home'], a: 1, why: 'Energy often returns **before** mood improves, so risk can **rise** in the early weeks. Keep monitoring closely.' },
{ id: 'q-mdd-2', wk: 12, link: 'c-mdd', stem: 'A patient taking phenelzine should avoid which foods? Select all that apply.', opts: ['Aged cheddar cheese', 'Salami', 'Fresh chicken', 'Draft (tap) beer', 'Cottage cheese'], a: [0, 1, 3], why: 'Aged, cured, fermented and tap beer are **high in tyramine** → hypertensive crisis with an MAOI. Fresh meat and cottage cheese are safe.' },
{ id: 'q-mdd-3', wk: 12, link: 'c-mdd', stem: 'A patient on sertraline who was recently given tramadol has a temperature of 39.5 °C, agitation, diaphoresis, tremor and hyperreflexia. The nurse suspects:', opts: ['Neuroleptic malignant syndrome', 'Serotonin syndrome', 'Hypertensive crisis', 'Lithium toxicity'], a: 1, why: 'Two serotonergic drugs + mental status change, autonomic instability and neuromuscular hyperactivity = **serotonin syndrome**. Stop the drugs; supportive care.' },
{"id":"q-mdd-4","wk":12,"link":"c-mdd","stem":"Which antidepressant class is most dangerous in overdose?","opts":["Selective serotonin reuptake inhibitors","Tricyclic antidepressants","SNRIs","Mirtazapine"],"a":1,"why":"TCAs cause fatal **cardiac dysrhythmias** in overdose; dispense small amounts to patients at risk for suicide."},
{"id":"q-mdd-5","wk":12,"link":"c-mdd","stem":"A severely withdrawn depressed patient sits silently. Which approach is best?","opts":["Ask a series of direct questions to get him talking","Sit with him, make simple observations and allow time","Leave him alone and return when he is ready to talk","Encourage him to cheer up"],"a":1,"why":"With slowed thinking, **offer self**, make **observations** and give **time**. Many questions overwhelm; platitudes minimize."},
{ id: 'q-mdd-6', wk: 12, link: 'c-mdd', stem: 'After ECT, which finding does the nurse expect?', opts: ['Permanent loss of long-term memory', 'Temporary confusion and short-term memory loss', 'Hypertensive crisis', 'Severe muscle pain from the seizure'], a: 1, why: 'Transient **confusion and short-term memory loss** are expected; a muscle relaxant prevents injury during the seizure.' },
{ id: 'q-mdd-7', wk: 12, link: 'c-mdd', stem: 'Which findings are vegetative signs of depression? Select all that apply.', opts: ['Early-morning awakening', 'Loss of appetite and weight', 'Decreased libido', 'Flight of ideas', 'Constipation'], a: [0, 1, 2, 4], why: 'Vegetative signs involve **sleep, appetite, sex and elimination**. Flight of ideas is a sign of mania.' },
{"id":"q-sui-1","wk":12,"link":"c-suicide","stem":"Which patient is at highest risk for suicide?","opts":["A 20-year-old woman with occasional thoughts of death and a supportive family","A 68-year-old widower who drinks daily, owns a gun and is withdrawing","A 35-year-old with NSSI who denies suicidal intent","A 45-year-old with anxiety who attends weekly therapy"],"a":1,"why":"Older male, widowed, alcohol use, **access to a firearm** and social withdrawal: many risk factors, few protective ones."},
{ id: 'q-sui-2', wk: 12, link: 'c-suicide', stem: 'Which interventions are part of suicide precautions with 1:1 observation? Select all that apply.', opts: ['Keep the patient within sight at all times, including in the bathroom', 'Remove belts, shoelaces and sharp objects', 'Check that each medication is swallowed', 'Have the patient sign a no-suicide contract instead of observation', 'Keep the patient’s hands visible while sleeping'], a: [0, 1, 2, 4], why: 'A **no-suicide contract** is not a safety measure and never replaces observation. A safety plan is used instead.' },
{"id":"q-sui-3","wk":12,"link":"c-suicide","stem":"A patient who has been severely depressed suddenly appears calm and is giving away her belongings. The nurse should:","opts":["Document the improvement and reduce the level of observation","Reassess suicide risk now and increase observation","Encourage her to share her belongings","Prepare her for discharge"],"a":1,"why":"Sudden calm and giving things away can mean she has **decided to die**. Reassess and increase observation."},
{ id: 'q-sui-4', wk: 12, link: 'c-suicide', stem: 'Which question is the best way to assess suicide risk?', opts: ['“You’re not thinking of hurting yourself, are you?”', '“Are you thinking about killing yourself?”', '“Why would you want to hurt yourself?”', '“Everyone has bad days. How was yours?”'], a: 1, why: 'Ask **directly**, using the word. Asking doesn’t plant the idea; leading or “why” questions discourage honesty.' },
{"id":"q-nssi-1","wk":12,"link":"c-nssi","stem":"A teen with fresh cuts on her forearms says she cuts “to make the pressure go away.” Which nursing response is best?","opts":["“Promise me you’ll never do this again.”","“Let me care for these cuts. What happened right before?”","“This is attention-seeking behavior, and we won’t reward it.”","“You’ll be restrained if you cut again.”"],"a":1,"why":"Calm, **nonjudgmental wound care** plus exploring **triggers** builds trust. Promises, labels and threats increase shame."},
{"id":"q-nssi-2","wk":12,"link":"c-nssi","stem":"Which therapy has the strongest evidence for nonsuicidal self-injury?","opts":["Electroconvulsive therapy","Dialectical behavior therapy","Cognitive processing therapy","Long-term psychoanalysis"],"a":1,"why":"**DBT** teaches distress tolerance, emotion regulation, mindfulness and interpersonal effectiveness."},
{ id: 'q-anx-1', wk: 12, link: 'c-anxiety', stem: 'A patient is having a panic attack. Which nursing actions are appropriate? Select all that apply.', opts: ['Stay with the patient', 'Use short, simple statements in a calm voice', 'Move the patient to a quieter area', 'Teach the patient about the causes of panic disorder', 'Guide slow breathing'], a: [0, 1, 2, 4], why: 'At **panic** level the patient cannot learn; teaching waits until anxiety is mild to moderate.' },
{ id: 'q-anx-2', wk: 12, link: 'c-anxiety', stem: 'A patient with GAD is prescribed buspirone. Which statement shows understanding?', opts: ['“I’ll take it when I feel a panic attack coming on.”', '“It may take 2 to 4 weeks before I notice it working.”', '“I can’t stop it suddenly or I’ll have seizures.”', '“It will make me very sleepy.”'], a: 1, why: 'Buspirone takes **2–4 weeks**, is **not PRN**, and has **no dependence or sedation**, unlike benzodiazepines.' },
{"id":"q-anx-3","wk":12,"link":"c-anxiety","stem":"A patient taking lorazepam asks about drinking wine at dinner. The nurse’s best response is:","opts":["“One glass with dinner is fine if you take it with food.”","“Avoid alcohol; together they can slow your breathing.”","“Take the lorazepam a few hours after dinner instead.”","“Alcohol makes lorazepam less effective, so skip it.”"],"a":1,"why":"Benzodiazepines + alcohol = **additive CNS and respiratory depression**."},
{"id":"q-ocd-1","wk":12,"link":"c-ocd","stem":"A newly admitted patient with OCD washes her hands for hours before breakfast. Which initial intervention is best?","opts":["Lock the bathroom","Allow time for the ritual, then gradually limit it","Tell her the ritual is unnecessary and she should stop","Skip breakfast until the ritual stops"],"a":1,"why":"Stopping a ritual abruptly sends anxiety soaring. **Allow time** at first, then limit it gradually with her."},
{ id: 'q-ocd-2', wk: 12, link: 'c-ocd', stem: 'Which treatment is first-line behavioral therapy for OCD?', opts: ['Exposure and response prevention', 'Flooding with no therapist present', 'Aversion therapy', 'Hypnosis'], a: 0, why: '**ERP**: exposure to the trigger while preventing the ritual, so the anxiety rises and falls on its own.' },
{ id: 'q-ptsd-1', wk: 12, link: 'c-ptsd', stem: 'A veteran has nightmares, flashbacks, an exaggerated startle response and avoids crowds 4 months after deployment. Which diagnosis fits the timing?', opts: ['Acute stress disorder', 'Posttraumatic stress disorder', 'Adjustment disorder', 'Generalized anxiety disorder'], a: 1, why: 'Trauma symptoms lasting **more than 1 month** = **PTSD**. Acute stress disorder is 3 days to 1 month.' },
{ id: 'q-ptsd-2', wk: 12, link: 'c-ptsd', stem: 'A patient with PTSD has a flashback in the dayroom. The nurse should first:', opts: ['Ask the patient to describe the trauma in detail', 'Use the patient’s name, orient him to where he is and that he is safe, and use grounding', 'Leave him alone until it passes', 'Give a PRN and place him in seclusion'], a: 1, why: '**Grounding and orientation** bring the patient back to the present. Don’t push for details.' },
{ id: 'q-ptsd-3', wk: 12, link: 'c-ptsd', stem: 'Which medication may be prescribed for PTSD-related nightmares?', opts: ['Prazosin', 'Lithium', 'Lamotrigine', 'Bupropion'], a: 0, why: '**Prazosin** (an alpha-1 blocker) reduces nightmares; watch for orthostatic hypotension.' },
{ id: 'q-ptsd-4', wk: 12, link: 'c-ptsd', stem: 'Three weeks after a car accident, a patient has intrusive memories and trouble sleeping. Which diagnosis fits best?', opts: ['PTSD', 'Acute stress disorder', 'Dissociative identity disorder', 'Bipolar II disorder'], a: 1, why: 'Symptoms between **3 days and 1 month** after a trauma = **acute stress disorder**.' },
// ---------- Chapter 3 · brain and psych meds ----------
{ id: 'q-neuro-1', wk: 11, link: 't-neuro', stem: 'Which neurotransmitter do benzodiazepines potentiate?', opts: ['Acetylcholine', 'Dopamine', 'GABA', 'Serotonin'], a: 2, why: 'Benzodiazepines bind the **GABA-A** receptor and increase chloride channel opening, calming neurons.', optionWhy: ['Acetylcholine is a separate neurotransmitter; the course links benzodiazepines to GABA receptors.', 'Dopamine is associated with other medication effects, not the receptor activity asked about here.', 'Correct: benzodiazepines enhance GABA-A signaling, which reduces neuronal activity.', 'Serotonin is affected by many antidepressants; it is not the transmitter potentiated by benzodiazepines.'] },
{ id: 'q-neuro-2', wk: 11, link: 't-neuro', stem: 'A patient with a seizure disorder is starting an antidepressant. Which one is contraindicated?', opts: ['Bupropion', 'Mirtazapine', 'Paroxetine', 'Venlafaxine'], a: 0, why: '**Bupropion** lowers the seizure threshold (also avoid it in eating disorders and abrupt alcohol or benzodiazepine withdrawal).', optionWhy: ['Correct: bupropion can lower the seizure threshold, making a seizure history especially important.', 'Mirtazapine is an antidepressant, but it is not the seizure-threshold concern identified in this question.', 'Paroxetine is an SSRI; it is not the specific seizure-risk answer in the course material.', 'Venlafaxine is an SNRI; it is not the specific seizure-risk answer in the course material.'] },
{ id: 'q-neuro-3', wk: 11, link: 't-neuro', stem: 'A patient taking trazodone gets dizzy when standing. Blockade of which receptor explains this?', opts: ['Alpha-1', 'Dopamine-2', 'Histamine-1', 'Muscarinic-1'], a: 0, why: '**Alpha-1** blockade dilates blood vessels → orthostatic hypotension. Teach to rise slowly.', optionWhy: ['Correct: alpha-1 blockade can lower vascular tone, causing blood pressure to drop on standing.', 'Dopamine-2 blockade is associated with antipsychotic effects and movement or hormone-related effects, not this positional dizziness.', 'Histamine-1 blockade is associated with sedation; it does not explain the blood-pressure change described.', 'Muscarinic blockade produces anticholinergic effects such as dry mouth and blurred vision.'] },
{ id: 'q-neuro-4', wk: 11, link: 't-neuro', stem: 'Which mood stabilizer most commonly causes hypothyroidism with long-term use?', opts: ['Carbamazepine', 'Lamotrigine', 'Lithium', 'Valproate'], a: 2, why: '**Lithium** interferes with thyroid hormone; check TSH at baseline and periodically.', optionWhy: ['Carbamazepine has other important adverse-effect and monitoring concerns, but the thyroid association asked about is linked to lithium.', 'Lamotrigine has a different high-priority safety concern, including serious rash; it is not the thyroid effect in this item.', 'Correct: long-term lithium can affect thyroid function, so monitoring is important.', 'Valproate has a distinct adverse-effect profile; it is not the common long-term thyroid effect being tested here.'] },
{ id: 'q-neuro-5', wk: 11, link: 't-neuro', stem: 'A patient on lamotrigine is started on another medication. Which one increases lamotrigine levels and the risk of Stevens-Johnson syndrome?', opts: ['Carbamazepine', 'Lithium', 'Quetiapine', 'Valproate'], a: 3, why: '**Valproate** raises lamotrigine levels, so the lamotrigine dose is halved.', optionWhy: ['Carbamazepine is another mood-stabilizing medication, but it is not the interaction identified in this question.', 'Lithium is a mood stabilizer, but the course material does not identify it as raising lamotrigine levels here.', 'Quetiapine is an antipsychotic, not the medication the course identifies as increasing lamotrigine levels.', 'Correct: valproate can increase lamotrigine levels, increasing the risk of a serious rash.'] },
{ id: 'q-neuro-6', wk: 11, link: 't-neuro', stem: 'Extrapyramidal symptoms from antipsychotics come from dopamine blockade in which pathway?', opts: ['Mesocortical', 'Mesolimbic', 'Nigrostriatal', 'Tuberoinfundibular'], a: 2, why: '**Nigrostriatal** = movement → EPS. Mesolimbic = the antipsychotic effect; tuberoinfundibular = prolactin.', optionWhy: ['The mesocortical pathway is associated with cognition and negative symptoms, not the movement pathway asked about.', 'The mesolimbic pathway is tied to positive symptoms and antipsychotic benefit; it is not the principal EPS pathway.', 'Correct: dopamine blockade in the nigrostriatal pathway disrupts motor control and can produce EPS.', 'The tuberoinfundibular pathway affects prolactin regulation, not the motor effects described.'] },
{ id: 'q-neuro-7', wk: 11, link: 't-neuro', stem: 'Which second-generation antipsychotic requires routine absolute neutrophil count (ANC) monitoring?', opts: ['Brexpiprazole', 'Clozapine', 'Risperidone', 'Ziprasidone'], a: 1, why: '**Clozapine** can cause life-threatening neutropenia: ANC weekly for 6 months, every 2 weeks for 6 months, then monthly.', optionWhy: ['Brexpiprazole is a second-generation antipsychotic, but the specific ANC risk in this question is associated with clozapine.', 'Correct: clozapine can severely lower neutrophils, so routine ANC monitoring is required.', 'Risperidone is a second-generation antipsychotic, but it is not the medication requiring this monitoring in this item.', 'Ziprasidone is a second-generation antipsychotic, but it is not the medication requiring this ANC schedule.'] },
{ id: 'q-neuro-8', wk: 11, link: 't-neuro', stem: 'Which drug does the assigned chapter identify as FDA approved specifically for postpartum depression?', opts: ['Brexanolone', 'Esketamine', 'Fluoxetine', 'Levomilnacipran'], a: 0, why: '**Brexanolone**: a 60-hour IV infusion with continuous pulse oximetry; the mother is accompanied while with her child. **Update:** its US approval was withdrawn in April 2025; oral **zuranolone** (Zurzuvae, approved 2023) is now the postpartum-depression drug. Answer the class exam the way your instructor taught it.', optionWhy: ['Correct: brexanolone is the medication identified in the course material for postpartum depression (its approval was withdrawn in 2025; zuranolone is current).', 'Esketamine is used in depression treatment, but the course does not identify it as the specific postpartum option here.', 'Fluoxetine is an SSRI antidepressant, but this question asks for the specific postpartum-approved medication.', 'Levomilnacipran is an SNRI antidepressant, not the postpartum-specific medication identified here.'] },
{ id: 'q-neuro-9', wk: 11, link: 't-neuro', stem: 'Which part of the brain coordinates voluntary motor movement and balance?', opts: ['Brainstem', 'Cerebellum', 'Cerebrum', 'Hypothalamus'], a: 1, why: 'The **cerebellum** smooths and coordinates movement and balance (why sedatives cause ataxia).', optionWhy: ['The brainstem regulates essential functions and pathways; it is not the primary movement-coordination structure asked about.', 'Correct: the cerebellum coordinates movement and helps maintain balance.', 'The cerebrum supports higher mental activity and voluntary movement, but fine coordination and balance point to the cerebellum.', 'The hypothalamus helps regulate drives and body systems; it is not the structure responsible for coordinating movement.'] },
{"id":"q-neuro-10","wk":11,"link":"t-neuro","stem":"A patient on a first-generation antipsychotic has dry mouth, blurred vision, constipation and urinary hesitancy. These effects come from blocking which receptors?","opts":["Histamine-1 (H1)","Muscarinic (acetylcholine)","Alpha-1 adrenergic","Serotonin 2A (5-HT2A)"],"a":1,"why":"**Muscarinic (M1)** blockade = anticholinergic effects. Tolerance to these usually does **not** develop.","optionWhy":["Histamine-1 blockade is more associated with sedation and appetite or weight effects.","Correct: blocking muscarinic acetylcholine receptors can cause dry mouth, blurred vision, constipation and urinary difficulty.","Alpha-1 blockade is associated with orthostatic blood-pressure changes, not this anticholinergic symptom cluster.","Serotonin 2A blockade contributes to atypical antipsychotic pharmacology; it does not explain the listed anticholinergic effects."]},
{ id: 'q-neuro-11', wk: 11, link: 't-neuro', stem: 'Which teaching points apply to a patient taking lithium? Select all that apply.', opts: ['Ibuprofen and hydrochlorothiazide can raise your lithium level', 'Large amounts of caffeine can lower your lithium level', 'Lithium has a wide margin of safety', 'Report vomiting or diarrhea to your provider', 'Your thyroid and kidney function will be checked'], a: [0, 1, 3, 4], why: 'Lithium has a **narrow** therapeutic index. NSAIDs, thiazides and ACE inhibitors raise it; caffeine lowers it; fluid loss raises it.', optionWhy: ['Correct: some anti-inflammatory drugs and thiazide diuretics can increase lithium levels and toxicity risk.', 'Correct: high caffeine intake can lower lithium levels; changes should be discussed with the prescriber.', 'Incorrect: lithium has a narrow safety range, so small level changes can matter.', 'Correct: vomiting or diarrhea can cause fluid loss and affect lithium concentration; report it promptly.', 'Correct: kidney and thyroid effects are important to monitor during lithium therapy.'] },
{"id":"q-neuro-12","wk":11,"link":"t-neuro","stem":"Pharmacokinetics describes:","opts":["What the drug does to the body at receptor sites","Absorption, distribution, metabolism and excretion","How strongly the drug binds to its receptors","The patient’s inherited risk of developing an illness"],"a":1,"why":"Kinetics = **ADME** (what the body does to the drug). Dynamics = what the drug does to the body.","optionWhy":["That is pharmacodynamics: the effects a medication has on the body.","Correct: pharmacokinetics follows absorption, distribution, metabolism and excretion (ADME).","Receptor binding describes how a drug acts, which belongs to pharmacodynamics.","Genetic risk concerns susceptibility to illness, not how the body processes a medication."]},
// ---------- Chapter 5 · culture ----------
{ id: 'q-cult-1', wk: 11, link: 't-culture', stem: 'A nurse is caring for a patient with limited English who is being assessed for suicidal thoughts. Who should interpret?', opts: ['The patient’s adult son', 'A bilingual housekeeper', 'A professional medical interpreter', 'The patient’s roommate'], a: 2, why: 'A **professional medical interpreter**. Family and friends may filter sensitive information and lack medical vocabulary.' },
{ id: 'q-cult-2', wk: 11, link: 't-culture', stem: 'A woman from Southeast Asia reports stomach pain and chest discomfort a month after her son died. The nurse suspects:', opts: ['Vulnerability', 'Acid reflux', 'Somatization', 'Transference'], a: 2, why: '**Somatization**: emotional distress expressed as physical symptoms; screen for grief and depression.' },
{ id: 'q-cult-3', wk: 11, link: 't-culture', stem: 'Which statements by the nurse support a culturally sensitive assessment? Select all that apply.', opts: ['“What do you call this illness?”', '“What do you think is causing it?”', '“How do you think it should be treated?”', '“Do you consider this a serious problem?”', '“Our medicine works better than home remedies.”'], a: [0, 1, 2, 3], why: 'Kleinman’s questions explore the patient’s own explanation. The last statement is **ethnocentric**.' },
{ id: 'q-cult-4', wk: 11, link: 't-culture', stem: 'Intergenerational conflict in immigrant families often happens because acculturation is:', opts: ['Ignored due to cultural beliefs', 'Filled with traumatic experiences', 'Easier for children', 'A function of assimilation'], a: 2, why: 'Children **acculturate faster** than older adults, so values clash.' },
{ id: 'q-cult-5', wk: 11, link: 't-culture', stem: 'Which nursing actions demonstrate cultural competence? Select all that apply.', opts: ['Planning mealtimes around the patient’s prayer schedule', 'Helping the patient visit with the chaplain', 'Finding out which foods a lacto-ovo vegetarian patient eats', 'Allowing time for the patient’s spiritual healer to visit', 'Ordering standard meal trays three times daily'], a: [0, 1, 2, 3], why: 'Each one adapts care to the patient’s beliefs; a standard tray ignores them.' },
{ id: 'q-cult-6', wk: 11, link: 't-culture', stem: 'In Campinha-Bacote’s model, which construct reduces stereotyping through direct interaction with patients of diverse backgrounds?', opts: ['Cultural awareness', 'Cultural encounters', 'Cultural desire', 'Cultural knowledge'], a: 1, why: 'Many **cultural encounters** show that individuals express their culture in individual ways.' },
{
  "id": "q-g34-01",
  "wk": 11,
  "link": "t-groups",
  "stem": "In a coping group, a participant hears others describe the same fear and says they had assumed nobody else felt it. Which therapeutic factor is most directly illustrated?",
  "opts": [
    "Universality",
    "Altruism",
    "Imparting information",
    "Imitative behavior"
  ],
  "a": 0,
  "why": "**Universality** is recognition of a shared experience. Altruism would emphasize benefit from helping another person. No teaching or copied behavior is described, so information-giving and imitation are less direct explanations.",
  "optionWhy": [
    "Universality means discovering that other people share a concern once thought unique; that is exactly what the member recognizes.",
    "Altruism is the value of helping other members, not recognizing that they have the same fear.",
    "Imparting information is the exchange of useful knowledge; no teaching or new facts are described.",
    "Imitative behavior means learning by observing or copying another member; the scenario is about shared experience."
  ]
},
{
  "id": "q-g34-02",
  "wk": 11,
  "link": "t-groups",
  "stem": "A nurse explains why a group may be useful while discussing its limits. Which statements are accurate? Select all that apply.",
  "opts": [
    "Members can practise interaction and receive peer feedback.",
    "Membership automatically makes every disclosure confidential.",
    "Several patients can receive help within the same session.",
    "A useful group must contain people with identical backgrounds.",
    "Members can learn from experiences beyond those of the leader."
  ],
  "a": [
    0,
    2,
    4
  ],
  "why": "Supported practice, several-person delivery and mutual learning are potential benefits. **Privacy cannot be guaranteed**, and useful groups may be heterogeneous. Similarity can affect fit, but identical backgrounds are not a requirement.",
  "optionWhy": [
    "Correct: members can try interaction skills and hear how peers experience them.",
    "Incorrect: the leader can set expectations, but cannot guarantee that every member will keep another member's disclosure private.",
    "Correct: a group can make one session available to several members at once.",
    "Incorrect: the group needs a suitable shared purpose, not identical life histories or backgrounds.",
    "Correct: members can learn from one another, not only from the facilitator."
  ]
},
{
  "id": "q-g34-03",
  "wk": 11,
  "link": "t-groups",
  "stem": "At the first meeting, members appear cautious. The nurse introduces the group’s purpose, explains expectations and invites introductions. Which development task is underway?",
  "opts": [
    "Evaluating termination",
    "Planning before recruitment",
    "Establishing orientation",
    "Performing an established task"
  ],
  "a": 2,
  "why": "The first session is doing **orientation** work: purpose, introductions and a safe frame. Planning sets these arrangements before the group meets. Termination reviews an ending, while performing assumes established norms and roles.",
  "optionWhy": [
    "Termination is the closing stage, when members review work and prepare for the group to end.",
    "Planning happens before the first session, when the leader defines purpose and arrangements.",
    "Correct: the opening meeting introduces the group, its purpose and expectations.",
    "Established work assumes members already know the group's structure and roles."
  ]
},
{"id":"q-g34-04","wk":11,"link":"t-groups","stem":"Members challenge a facilitator’s authority during a disagreement. No one is threatening harm. Which interpretation best guides the response?","opts":["Conflict this strong shows the group should be ended for safety.","Storming can be part of working; help them resolve it safely.","Challenging the leader means the group is entering termination.","The leader should withdraw all structure immediately."],"a":1,"why":"**Storming** can include clashes and challenges during working. Constructive resolution supports development. Automatically ending the group avoids the task, and either calling it termination or abandoning structure misreads the need.","optionWhy":["Disagreement alone does not mean the group is unsafe or should be ended; first address it within the group's safety limits.","Correct: challenges and disagreement can occur during storming; the leader helps members work through them safely.","Termination is the planned ending, not a label for conflict about authority.","Removing all structure leaves members without the boundaries needed to handle disagreement constructively."]},
{
  "id": "q-g34-05",
  "wk": 11,
  "link": "t-groups",
  "stem": "A participant notices that two members have not spoken and creates an opening for their views. Which role is being performed?",
  "opts": [
    "Recognition seeker",
    "Information giver",
    "Blocker",
    "Gatekeeper"
  ],
  "a": 3,
  "why": "A **gatekeeper**, a maintenance role, supports access to participation. An information giver supplies content, a recognition seeker draws attention to self, and a blocker obstructs the work.",
  "optionWhy": [
    "A recognition seeker tries to draw attention to their own status or contribution, rather than inviting others in.",
    "An information giver contributes facts or experience to the group's task.",
    "A blocker slows or diverts the group's work instead of opening participation.",
    "Correct: a gatekeeper helps balance participation and makes room for quieter members."
  ]
},
{
  "id": "q-g34-06",
  "wk": 11,
  "link": "t-groups",
  "stem": "Which referral best fits a group for co-occurring mental illness and substance use?",
  "opts": [
    "Panic disorder with cannabis use disorder",
    "Social anxiety with a reading difficulty",
    "Insomnia with seasonal allergies",
    "Bipolar disorder with obsessive-compulsive disorder but no substance use disorder"
  ],
  "a": 0,
  "why": "A **dual-diagnosis group** in this chapter addresses a mental disorder together with a substance use disorder. Two psychiatric diagnoses alone, or an unrelated physical or learning concern, do not establish that particular group purpose.",
  "optionWhy": [
    "Correct: the referral includes a psychiatric disorder and a substance use disorder, matching the group's purpose.",
    "A learning difficulty with anxiety does not identify a substance use disorder.",
    "Insomnia with allergies pairs a symptom and a physical condition, not the two target diagnoses.",
    "Both conditions named are psychiatric; the scenario does not include a substance use disorder."
  ]
},
{
  "id": "q-g34-07",
  "wk": 11,
  "link": "t-groups",
  "stem": "A nurse preserves the safety rules but asks members to compare options and jointly decide how to practise a coping skill. Which leadership style predominates?",
  "opts": [
    "Autocratic",
    "Democratic",
    "Laissez-faire",
    "Leadership is absent"
  ],
  "a": 1,
  "why": "**Democratic** leadership supports shared problem solving and interaction within a therapeutic frame. An autocratic leader retains the decision; laissez-faire provides much less direction. Maintaining boundaries shows that leadership remains active.",
  "optionWhy": [
    "Autocratic leadership keeps decision-making mainly with the leader, unlike the members' shared choice here.",
    "Correct: the leader keeps safety limits while involving members in decisions and practice.",
    "Laissez-faire leadership gives the group little direction; the nurse here is actively maintaining structure.",
    "The leader is present and guiding the process, so leadership is not absent."
  ]
},
{
  "id": "q-g34-08",
  "wk": 11,
  "link": "t-groups",
  "stem": "Before an in-person group begins, which actions support informed participation and privacy? Select all that apply.",
  "opts": [
    "Explain likely benefits, risks and confidentiality limits.",
    "Guarantee that peers have the same professional duties as the nurse.",
    "Discuss expectations about leaving and contact outside the group.",
    "Address devices, photographs and recording.",
    "Describe disclosure as risk-free once everyone signs an agreement."
  ],
  "a": [
    0,
    2,
    3
  ],
  "why": "Consent includes risks, boundaries and confidentiality limits, with clear expectations about devices and outside contact. Peers are not governed by the nurse’s professional code, and an agreement does not remove every possibility of disclosure. **Never promise absolute confidentiality.**",
  "optionWhy": [
    "Correct: participants need an honest explanation of likely benefits, risks and the limits of privacy before agreeing.",
    "Incorrect: peers are group members, not clinicians bound by the nurse's professional confidentiality duties.",
    "Correct: expectations about attendance, leaving and outside contact help members understand the group's boundaries.",
    "Correct: discussing recording, photos and devices helps protect privacy.",
    "Incorrect: an agreement can set expectations, but it cannot make disclosure risk-free or guarantee that everyone will comply."
  ]
},
{"id":"q-g34-09","wk":11,"link":"t-groups","stem":"A member repeatedly speaks over others after a general reminder. Which nurse response gives the most useful direct feedback?","opts":["“Please stop talking so much; others need a turn too.”","“The group feels you’re taking over the discussion again.”","“I’ve interrupted several times; I want to make room for others.”","“Let’s go around the circle so each person gets a turn.”"],"a":2,"why":"The nurse identifies an observed pattern and its effect on participation, then supports a boundary. A character label shames the person; speaking for everyone assumes feelings the nurse has not verified. Giving up shared airtime reinforces the problem.","optionWhy":["This tells the member what to stop but gives no specific feedback about the effect on the group.","Speaking for the whole group can feel like an attack and is not the nurse’s own direct observation.","Correct: it names the nurse's observable action and its effect, then makes room for others without attacking the member.","A structure can help, but it avoids giving the member direct feedback."]},
{
  "id": "q-g34-10",
  "wk": 11,
  "link": "t-groups",
  "stem": "A quiet member says they are still organizing their thoughts. Which next response best supports participation?",
  "opts": [
    "Demand an immediate account of their most painful experience.",
    "Offer a little time and agree to return to the member with the prompt.",
    "Explain that silence proves they are refusing treatment.",
    "Permanently exclude the member because others speak faster."
  ],
  "a": 1,
  "why": "Time and a predictable invitation can help a member formulate a contribution. Silence may reflect thoughtfulness or uncertainty about safety. Forced disclosure, labeling and exclusion ignore those possibilities.",
  "optionWhy": [
    "Demanding a painful disclosure can pressure the member and is not necessary to invite participation.",
    "Correct: allowing time and offering a predictable return gives the member choice while keeping them included.",
    "Silence alone does not prove refusal; this interpretation is judgmental and unsupported.",
    "Exclusion removes the chance to participate and treats a difference in pace as misconduct."
  ]
},
{
  "id": "q-g34-11",
  "wk": 11,
  "link": "t-groups",
  "stem": "A novice facilitator is reviewing group fit and backup needs. Which findings call for assessment and experienced clinical support rather than routine unsupervised group management? Select all that apply.",
  "opts": [
    "Active paranoid beliefs are interfering with trust in the session.",
    "A quiet member reports thoughts of acting on suicide tonight.",
    "A member has limited income but is attentive and follows the discussion.",
    "Acute mania prevents a member from attending to the group or respecting basic boundaries.",
    "A member listens carefully and asks for thinking time."
  ],
  "a": [
    0,
    1,
    3
  ],
  "why": "Assess the actual safety and participation needs associated with paranoia, possible imminent suicide risk and acute mania. Seek supervision, backup or individual stabilization as appropriate. **Quiet behavior can coexist with serious risk**; poverty and thoughtful silence alone are not exclusion criteria. These findings do not justify permanent diagnosis-based bans.",
  "optionWhy": [
    "Correct: paranoid beliefs that interfere with trust may prevent safe participation and call for assessment and experienced support.",
    "Correct: a stated plan to act tonight is an immediate safety concern that requires urgent assessment and support.",
    "Limited income alone does not establish that the person cannot participate safely or benefit from the group.",
    "Correct: acute mania that disrupts attention and boundaries may require stabilization and additional clinical support.",
    "Quietness and a request for time do not by themselves show risk or inability to participate."
  ]
},
{"id":"q-g34-12","wk":11,"link":"t-groups","stem":"A medication-education group is being evaluated. Which observation gives the strongest evidence that its learning goal was met?","opts":["Every participant attended the full hour and took the handouts home.","Members rated the group as very helpful on the evaluation form.","Members explain their own medicines’ purpose, timing and key risks.","The facilitator covered every planned topic within the hour."],"a":2,"why":"Demonstrated medication knowledge matches the **education outcome**. Attendance and a smooth lecture do not show understanding, and accepting cost is not a knowledge outcome or a prerequisite for care. Use teach-back and address any practical barriers.","optionWhy":["Attendance shows presence, not whether participants learned the material.","Satisfaction ratings do not show that members learned the content.","Correct: explaining an individual plan demonstrates understanding of the educational content.","Covering the topics shows what was taught, not what members learned."]}
];
// Appended so existing Learn checkpoint positions remain unchanged.
window.MH_Q.push({ id:'q-e4-dsm-purpose',wk:11,link:'t-dx',stem:'A student asks what the DSM contributes to mental health care. Which explanation is most accurate?',opts:['A shared set of criteria for classifying mental disorders','A complete nursing care plan for every person with the same diagnosis','A laboratory test that confirms every mental disorder'],a:0,why:'The DSM supplies **diagnostic criteria and shared terminology**. A diagnostic category does not replace assessment or provide an individualized nursing care plan, and it is not a laboratory test.' });
window.MH_Q.push({ id:'q-e4-nursing-response',wk:11,link:'t-dx',stem:'The team has identified a mental disorder using diagnostic criteria. When developing the nursing plan, what should the nurse identify in addition to that label?',opts:['The individual patient’s responses, needs, risks and measurable outcomes','The same interventions for everyone who has that diagnosis','A diagnosis label that makes further assessment unnecessary'],a:0,why:'Nursing care addresses the **individual’s responses and needs** and uses measurable patient-centered outcomes. A shared diagnosis can support communication, but it does not make every person’s assessment and interventions identical.' });
window.MH_Q.push({ id: 'q-e4-peplau-working', wk: 11, link: 't-relationship', stem: 'The nurse and patient identify situations that trigger distress and rehearse a coping skill together. Which phase of their therapeutic relationship is this?', opts: ['Preorientation', 'Orientation', 'Working', 'Termination'], a: 2, why: 'The **working** phase uses the established relationship to explore problems and practise coping. Orientation establishes the relationship and its agreement; termination reviews progress and closes it. Preorientation is preparation before meeting the patient.', optionWhy: ['Preorientation is the nurse’s preparation before the patient relationship begins.', 'Orientation establishes trust, goals, roles, boundaries and the planned ending; the relationship is still being set up.', 'Correct: identifying triggers and practising coping are active therapeutic work after orientation.', 'Termination reviews what has been accomplished and prepares for closure rather than beginning new work.'], source: 'https://www.ncbi.nlm.nih.gov/sites/books/NBK610828/' });
